import{z as o,x as p,o as t,c as s,q as r,j as l,D as E,d as n,s as A,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"两部收费与捆绑","description":"","frontmatter":{"title":"两部收费与捆绑","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/two-part-bundling.md","filePath":"econ/two-part-bundling.md","lastUpdated":1791413859000}'),m={name:"econ/two-part-bundling.md"};function d(C,a,h,D,u,_){const B=p("Mermaid");return t(),s("div",null,[a[2]||(a[2]=r('<h1 id="两部收费与捆绑" tabindex="-1">两部收费与捆绑 <a class="header-anchor" href="#两部收费与捆绑" aria-label="Permalink to &quot;两部收费与捆绑&quot;">​</a></h1><div class="epigraph"><p>入场费抽取剩余，使用费贴近边际成本；把几种商品捆成一包，利用的是评价的负相关，不是再按组别贴一个勒纳。</p><footer>—— 据 Oi, A Disneyland Dilemma, QJE, 1971；Adams and Yellen, Commodity Bundling and the Burden of Monopoly, QJE, 1976 整理</footer></div><p>定位：<a href="/econ/price-discrimination">上一课</a>。三级歧视按可观察组别给出 \\(L_i=1/|\\varepsilon_i|\\)。本课不重讲分箱与套利。缺口是菜单：卖方往往看不见组别标签，却能收一笔固定费再加使用费，或把几种产品捆成包。这是 Pigou 的二级方向，不是把三级勒纳再写一遍。<a href="/econ/natural-monopoly-ramsey">拉姆齐</a>的线性次优在此被非线性价目部分替代。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两部收费 \\((A,p)\\)：先付 \\(A\\) 才获得以单价 \\(p\\) 购买 \\(q\\) 的权利。消费者剩余 \\(\\mathrm{CS}(p)\\) 若低于 \\(A\\) 则退出。同质消费者且能挡转售时，最优是 \\(p=\\mathrm{MC}\\)、\\(A=\\mathrm{CS}(\\mathrm{MC})\\)：产量有效，剩余全归卖方——效率上像一级歧视，信息不要求看见每个人的边际评价，只要求他们相同。缺口是：<strong>异质时 \\(A\\) 会被低需求者卡住，使用费被迫离开 MC。</strong></p><p>捆绑：两种商品的保留价格 \\((v_1,v_2)\\)，纯捆绑只卖包，混合捆绑包与单品都卖。Adams–Yellen 的机制是负相关评价：单独定价会丢掉「对 A 很热、对 B 很冷」的人，打包把总和拉过成本。这不是三级的组间弹性，不要把捆绑写成「把两种商品当两个组别」。</p><h3 id="两部收费不是拉姆齐线性税" tabindex="-1">两部收费不是拉姆齐线性税 <a class="header-anchor" href="#两部收费不是拉姆齐线性税" aria-label="Permalink to &quot;两部收费不是拉姆齐线性税&quot;">​</a></h3><p>拉姆齐用一组线性 \\(P_i\\) 分摊固定成本。两部收费把固定成本（或垄断租金）放进 \\(A\\)，让 \\(p\\) 承担配置。同质时第一优可恢复；异质时 \\(A\\) 有排除效应，与拉姆齐在「谁被赶出市场」上权衡不同。本课不把二者写成同一个乘子。</p><p><span class="marginnote">Oi 的迪士尼乐园：公园入场费加园内边际成本定价。若游客同质，这是教科书最优；游客异质时，入场费要迁就边际游客，园内价格可能高于 MC 以抽取高需求者。</span></p><p><span class="marginnote">数字实例：游乐园单项成本 5 元。游客同质、人均愿付 100 元时，最优是门票收走全部剩余、项目单价定 5 元；一旦混入一批只愿付 40 元的游客，门票最高只能收到 40，单价就得抬到 5 元以上去补高需求者的钱——低价客卡住了门票，高价客付出超额单价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>同质：直接验证 \\(p=\\mathrm{MC}\\)、\\(A=\\mathrm{CS}\\)。异质：类型 \\(\\theta\\) 的需求 \\(q(p,\\theta)\\)，参与约束 \\(A\\le\\mathrm{CS}(p,\\theta)\\) 对边际类型紧。提高 \\(p\\) 放松对高类型抽取的限制，但扭曲用量；最优 \\(p\\gt \\mathrm{MC}\\) 是次优。连续类型、激励相容的非线性价目接到<a href="/econ/screening-rent">筛选</a>，本课只钉两部这一维。</p><p>捆绑：比较三种利润——分开卖、只卖包、混合。评价独立或正相关时，捆绑增益小；负相关时包的需求更集中。成本超可加会吃掉捆绑的理由。不要用三级的 \\(\\mathrm{MR}_i=\\mathrm{MC}\\) 套到包上而不声明需求如何加总。</p><p>保留价格若在成本之下的象限，打包可能强迫消费无价值的那一件，利润比较必须把这块浪费算进去。</p>',14)),(t(),l(i,null,{default:E(()=>[A(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20TD%5B%22%E4%B8%89%E7%BA%A7%EF%BC%9A%E7%BB%84%E6%A0%87%E7%AD%BE%20%2B%20%E7%BA%BF%E6%80%A7%E4%BB%B7%22%5D%20--%3E%20TP%5B%22%E4%B8%A4%E9%83%A8%EF%BC%9A(A%2C%20p)%22%5D%0A%20%20TP%20--%3E%20HOM%5B%22%E5%90%8C%E8%B4%A8%EF%BC%9Ap%20%3D%20MC%EF%BC%8CA%20%3D%20CS%22%5D%0A%20%20TP%20--%3E%20HET%5B%22%E5%BC%82%E8%B4%A8%EF%BC%9AA%20%E6%8E%92%E9%99%A4%EF%BC%8Cp%20%E7%A6%BB%E5%BC%80%20MC%22%5D%0A%20%20TD%20--%3E%20BUN%5B%22%E6%8D%86%E7%BB%91%EF%BC%9A%E7%9B%B8%E5%85%B3%E8%AF%84%E4%BB%B7%22%5D%0A%20%20BUN%20--%3E%20MIX%5B%22%E7%BA%AF%E6%8D%86%20vs%20%E6%B7%B7%E5%90%88%E6%8D%86%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"本课仍是一家卖方。对面出现第二家之后，两部与捆绑变成策略变量，不在这里写反应函数。也不把「打包」写成限价簿的冰山单。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"抽取剩余的机制是参与约束：固定费把无差异曲线「整块」搬进卖方口袋，使用费决定沿需求走多远。同质时没有人被排除，MC 定价不伤害抽取；异质时固定费的高度由最不愿意进门的人决定，高类型留下信息租金——二级歧视的核心，三级看不见这个租金，因为它按标签定价、不让人自选。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：「参与约束」就是「人家干不干」的条件——顾客付完钱后至少不比在家待着差，才肯进门。固定费能收多高，正好被「最不情愿的顾客刚好不亏」这条线卡住。")],-1)),(t(),l(i,null,{default:E(()=>[A(B,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOW%5B%22%E8%BE%B9%E9%99%85%E4%BD%8E%E9%9C%80%E6%B1%82%E8%80%85%22%5D%20--%3E%20PIN%5B%22%E5%85%A5%E5%9C%BA%E8%B4%B9%20A%20%E8%A2%AB%E4%BB%96%E7%9A%84%E5%89%A9%E4%BD%99%E5%8D%A1%E4%BD%8F%22%5D%0A%20%20PIN%20--%3E%20RAISE%5B%22%E5%8D%96%E6%96%B9%E6%83%B3%E5%90%91%E9%AB%98%E9%9C%80%E6%B1%82%E8%80%85%E5%A4%9A%E6%8A%BD%22%5D%0A%20%20RAISE%20--%3E%20UP%5B%22%E6%8A%AC%E9%AB%98%E4%BD%BF%E7%94%A8%E8%B4%B9%20p%2C%20%E4%BD%BF%E5%85%B6%E7%A6%BB%E5%BC%80%20MC%22%5D%0A%20%20UP%20--%3E%20DIST%5B%22%E4%BD%8E%E7%B1%BB%E5%9E%8B%E7%94%A8%E9%87%8F%E8%A2%AB%E6%89%AD%E6%9B%B2%22%5D%0A%20%20UP%20--%3E%20RENT%5B%22%E9%AB%98%E7%B1%BB%E5%9E%8B%E7%95%99%E4%B8%8B%E4%BF%A1%E6%81%AF%E7%A7%9F%E9%87%91%22%5D%0A%20%20DIST%20--%3E%20SECOND%5B%22%E6%AC%A1%E4%BC%98%3A%20%E6%8A%BD%E5%8F%96%E4%B8%8E%E6%95%88%E7%8E%87%E7%9A%84%E6%8A%98%E4%B8%AD%E7%82%B9%22%5D%0A%20%20RENT%20--%3E%20SECOND%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">常见误区：初学者容易以为捆绑总能多赚钱。实际上它靠的是大家对两样东西的口味互相错开（评价负相关）；若口味同涨同跌（正相关），打包几乎白捆，还可能把只想买一件的人挡在门外。</span></p><p>捆绑的机制是保留价格求和。负相关使 \\(v_1+v_2\\) 的方差小于分开卖时的两支需求，更接近单一垄断价格下的完全抽取。正相关则打包几乎不增加抽取，还可能因为必须接受不喜欢的那一件而排除用户。</p><p>混合捆绑保留「只买一件」的出口，减少排除，但给高评价者留下自选租金，利润比较要算。单位需求教具上，Adams–Yellen 用矩形把四种人（热–热、热–冷、冷–热、冷–冷）画清楚；连续需求时同一相关结构仍在，只是积分替代计数。互补品打折是另一条理由，不要与评价负相关混成一个「打包总是好」。</p><p><span class="marginnote">Adams–Yellen 1976 的图是单位需求、0–1 消费的矩形。连续需求、互补品打折，机制仍是评价相关，不要退化成「捆绑等于三级里的第三组」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>转售把 \\(A\\) 冲掉：一人付费、多人用，两部崩溃。规制若禁止 \\(A\\)（只许线性价），退回拉姆齐。耐用品、跨期承诺会改 \\(A\\) 的可信性。高峰负荷把「同一商品不同时点」当成容量约束，下一课接，不是把一天拆成三级组别。连续类型的最优非线性价目把两部嵌进一整个 \\(T(q)\\)，本课只留二维菜单。</p><p>捆绑若含互补的接口或售后，评价相关被技术锁死，Adams–Yellen 的矩形不再够用。</p><p>后课默认：同质两部可恢复 \\(p=\\mathrm{MC}\\)；异质两部与捆绑是二级工具，不是三级勒纳的重贴标签。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两部收费用 \\(A\\) 抽剩余、用 \\(p\\) 管用量；同质时有效，异质时次优。</li><li>捆绑利用评价相关，尤其是负相关；不是组别勒纳。</li><li>与拉姆齐线性税对照：非线性把固定成本从边际价格里拆出去。</li><li>下一课把固定成本换成时点上的容量影子价格。</li><li>出处：Oi, <em>QJE</em>, 1971；Adams and Yellen, <em>QJE</em>, 1976。</li></ul>',10))])}const T=o(m,[["render",d]]);export{f as __pageData,T as default};
